window.AWARENESS = {
"fr": [
  {"id": "click", "title": "Ne cliquez jamais sans lire", "summary": "La plupart des attaques commencent par un clic réflexe sur un lien, une pièce jointe ou un bouton « OK ».",
   "details": ["Les pirates comptent sur la précipitation : un message alarmant (« votre compte sera fermé »), une promotion limitée, un colis en attente. Prenez trois secondes pour lire l'adresse de l'expéditeur, survoler le lien pour voir où il mène vraiment et vous demander si vous attendiez ce message.", "Un lien peut afficher « www.mabanque.ch » et pointer vers un tout autre site. Sur un ordinateur, survolez le lien : la vraie destination s'affiche en bas de la fenêtre. Sur un téléphone, appuyez longuement pour la voir."],
   "tips": ["Lisez l'adresse complète de l'expéditeur, pas seulement le nom affiché.", "Survolez les liens avant de cliquer ; en cas de doute, tapez vous-même l'adresse du site.", "Aucune banque, administration ou service sérieux ne demande un mot de passe par e-mail.", "Un message qui vous presse d'agir est un signal d'alerte, pas une urgence."]},
  {"id": "phishing", "title": "Reconnaître le phishing (hameçonnage)", "summary": "Un faux message imite une entreprise connue pour vous faire saisir vos identifiants ou votre carte bancaire.",
   "details": ["Le phishing prend la forme d'e-mails, de SMS (« smishing »), de messages WhatsApp ou d'appels. Le message copie le logo et le style d'une banque, de La Poste, de Swisscom, d'un impôt, d'Amazon… et vous envoie vers une page de connexion qui est une copie. Tout ce que vous y saisissez part directement chez le pirate.", "Les indices classiques : adresse d'expéditeur approximative (support@swiss-post-secure.com), fautes ou tournures étranges, salutation générique (« Cher client »), demande de paiement d'une petite somme (frais de douane à 2,90 CHF), menace de blocage."],
   "tips": ["Ne vous connectez jamais depuis un lien reçu : ouvrez l'application ou tapez l'adresse officielle.", "Comparez l'adresse du site avec celle que vous utilisez d'habitude, lettre par lettre.", "Signalez le message à l'entreprise imitée et supprimez-le.", "Si vous avez saisi un mot de passe sur un faux site, changez-le immédiatement partout où il est utilisé."]},
  {"id": "ceo_fraud", "title": "La direction piratée : fraude au président", "summary": "Un e-mail semblant venir de votre chef ou d'un collègue demande un virement urgent ou des données confidentielles.",
   "details": ["Les pirates étudient l'entreprise (site web, LinkedIn) puis envoient un message très plausible : « Je suis en réunion, fais ce virement de 12 000 CHF avant midi, je t'explique après. » Parfois la boîte e-mail du dirigeant a réellement été piratée, ce qui rend le message authentique en apparence.", "Le levier est toujours le même : autorité, urgence et confidentialité (« n'en parle à personne »). Aucune procédure normale ne fonctionne ainsi."],
   "tips": ["Toute demande de virement, de changement d'IBAN ou de données sensibles se confirme par téléphone, avec un numéro que vous connaissez déjà.", "Méfiez-vous de l'urgence et du secret : ce sont les signatures de l'arnaque.", "Une adresse d'expéditeur légitime ne prouve rien si le compte a été piraté.", "Instaurez la règle des quatre yeux pour les paiements."]},
  {"id": "unusual_mail", "title": "Un e-mail inhabituel ? Vérifiez par un autre canal", "summary": "Un correspondant connu qui écrit différemment, à une heure étrange, avec une pièce jointe inattendue : ne répondez pas dans le fil.",
   "details": ["Quand un compte e-mail est piraté, l'attaquant envoie des messages à tous les contacts, souvent en réponse à de vraies conversations passées. Le ton, la langue ou la signature peuvent changer légèrement, la pièce jointe est un « document » ou une « facture » que personne n'attendait.", "Le bon réflexe est de vérifier par un autre canal : un appel, un SMS, une conversation en personne. Ne répondez pas au message lui-même, l'attaquant lit les réponses."],
   "tips": ["Comparez le style : formules, langue, signature, heure d'envoi.", "N'ouvrez pas une pièce jointe que vous n'attendiez pas, même d'un proche.", "Appelez la personne pour confirmer avant d'ouvrir ou de payer.", "Prévenez votre contact si vous pensez que son compte est piraté."]},
  {"id": "double_ext", "title": "salaires.xlsx.exe : le piège de la double extension", "summary": "Un fichier nommé « salaires.xlsx.exe » ou « facture.pdf.sh » n'est pas un tableau ni un PDF : c'est un programme.",
   "details": ["Le système ne regarde que la dernière extension. « salaires.xlsx.exe » est un exécutable Windows, « rapport.pdf.sh » un script Linux, « photo.jpg.desktop » un lanceur. En double-cliquant, vous exécutez un programme inconnu avec vos droits : il peut chiffrer vos documents ou voler vos mots de passe.", "Les extensions dangereuses sous Linux sont notamment .sh, .run, .bin, .desktop, .AppImage, .py, .pl, .deb provenant d'une source inconnue. Sous Windows : .exe, .scr, .bat, .cmd, .js, .vbs, .msi. Le système peut aussi masquer les extensions connues, d'où l'importance de les afficher."],
   "tips": ["Affichez toujours les extensions de fichiers dans le gestionnaire de fichiers.", "Un document ne devrait jamais avoir deux extensions.", "N'exécutez jamais un fichier reçu par e-mail ou messagerie sans l'avoir analysé et vérifié auprès de l'expéditeur.", "Sur Linux, un fichier n'est exécutable que si vous lui en donnez le droit : ne le faites pas pour un fichier inconnu."]},
  {"id": "usb", "title": "Clés USB : trouvées, offertes… ou piégées", "summary": "Une clé trouvée sur un parking ou reçue en cadeau peut contenir un cheval de Troie, ou même se faire passer pour un clavier.",
   "details": ["Les pirates abandonnent volontairement des clés infectées près des entreprises : la curiosité fait le reste. Certaines clés « BadUSB » se déclarent comme un clavier et tapent des commandes à votre place en quelques secondes, sans qu'aucun fichier ne soit visible.", "ClamAV Antivirus GUI analyse les clés USB avant de les ouvrir, mais cela ne protège pas contre une clé-clavier ni contre un programme que vous lanceriez vous-même. Une clé de provenance inconnue ne se branche pas."],
   "tips": ["Ne branchez jamais une clé USB dont vous ne connaissez pas l'origine.", "Laissez l'analyse automatique se terminer avant d'ouvrir les fichiers.", "N'exécutez aucun programme depuis une clé, copiez seulement les documents.", "Pour échanger des fichiers, préférez un partage en ligne ou un envoi chiffré."]},
  {"id": "malware_types", "title": "Virus, ver, cheval de Troie, cryptolocker : les différences", "summary": "Tous sont des logiciels malveillants, mais ils n'entrent pas et n'agissent pas de la même manière.",
   "details": ["Un virus s'attache à un programme ou un document et se propage quand on l'ouvre. Un ver se répand tout seul d'un ordinateur à l'autre par le réseau, en exploitant une faille, sans intervention humaine. Un cheval de Troie (trojan) se présente comme un logiciel utile (jeu, utilitaire, « lecteur vidéo ») mais ouvre une porte dérobée : vol de mots de passe, espionnage de la webcam, contrôle à distance.", "Un cryptolocker (rançongiciel, ransomware) chiffre vos fichiers et exige une rançon pour la clé. Il arrive souvent par une pièce jointe ou un cheval de Troie. Sans sauvegarde, les données sont généralement perdues, et payer ne garantit rien."],
   "tips": ["Le cheval de Troie est le plus courant aujourd'hui : méfiez-vous des logiciels « gratuits » hors des sources officielles.", "Un ver exploite les failles : les mises à jour sont votre protection.", "Contre un cryptolocker, seule une sauvegarde hors ligne vous sauve.", "L'antivirus détecte les menaces connues ; les nouvelles passent parfois entre les mailles."]},
  {"id": "vulnerability", "title": "C'est quoi une faille de sécurité ?", "summary": "Une erreur dans un programme qui permet à un attaquant de faire ce qu'il ne devrait pas pouvoir faire.",
   "details": ["Les logiciels contiennent des millions de lignes de code écrites par des humains. Certaines erreurs permettent de faire planter le programme, d'y injecter des commandes ou de prendre le contrôle de la machine simplement en ouvrant une image, une page web ou un document piégé. Chaque faille connue reçoit un numéro CVE (par exemple CVE-2026-63072).", "Entre la publication d'une faille et sa correction, les pirates automatisent l'attaque de tous les ordinateurs non mis à jour. L'onglet Sécurité de cette application montre les failles connues des programmes installés et si un correctif existe."],
   "tips": ["Une faille « critique » ou « haute » sans correctif mérite de désinstaller ou de ne pas utiliser le programme concerné.", "Moins vous avez de logiciels installés, moins vous avez de failles.", "Les navigateurs et lecteurs de documents sont les plus exposés : gardez-les à jour.", "Une faille n'est pas une infection ; c'est une porte non verrouillée."]},
  {"id": "updates", "title": "Pourquoi les mises à jour sont vitales", "summary": "Les mises à jour de sécurité ferment les failles que les pirates exploitent déjà.",
   "details": ["Une mise à jour de sécurité n'apporte pas de nouveautés visibles : elle corrige une faille. Une fois le correctif publié, la faille est connue de tous, y compris des attaquants, qui visent les machines en retard. Un ordinateur non mis à jour pendant des mois est une cible facile.", "Sur Linux Mint, le Gestionnaire de mises à jour et cette application vous signalent les mises à jour de sécurité (rouge), recommandées (applications) et décalées. Redémarrez quand on vous le demande : certaines corrections (noyau) ne sont actives qu'après."],
   "tips": ["Installez les mises à jour de sécurité dès qu'elles apparaissent.", "Activez les mises à jour automatiques si vous oubliez souvent.", "Mettez aussi à jour les applications Flatpak, les extensions de navigateur et le firmware.", "Un logiciel qui n'est plus mis à jour par son éditeur doit être remplacé."]},
  {"id": "passwords", "title": "Mots de passe et double authentification", "summary": "Un mot de passe unique et long par service, plus une deuxième vérification : c'est la base.",
   "details": ["Quand un site est piraté, les mots de passe volés sont testés automatiquement sur des centaines d'autres services. Réutiliser le même mot de passe revient à donner une clé qui ouvre toutes vos portes. La longueur compte plus que la complexité : une phrase de quatre ou cinq mots est plus sûre qu'un « P@ssw0rd! ».", "Un gestionnaire de mots de passe (Bitwarden, KeePassXC…) crée et retient des mots de passe uniques pour vous. La double authentification (code par application, clé de sécurité) bloque un pirate même s'il connaît le mot de passe."],
   "tips": ["Un mot de passe différent pour chaque service, géré par un gestionnaire de mots de passe.", "Activez la double authentification sur l'e-mail, la banque et les réseaux sociaux en priorité.", "Ne partagez jamais un code reçu par SMS, même avec un « conseiller ».", "Vérifiez sur haveibeenpwned.com si votre adresse apparaît dans une fuite."]},
  {"id": "backups", "title": "Sauvegardes : votre assurance contre tout", "summary": "Face à un rançongiciel, une panne ou un vol, seule une sauvegarde récente et hors ligne vous sauve.",
   "details": ["Une sauvegarde utile est automatique, régulière et déconnectée : un disque externe que vous branchez puis débranchez, ou un service en ligne avec versions. Un disque branché en permanence sera chiffré en même temps que l'ordinateur par un cryptolocker.", "Règle 3-2-1 : trois copies de vos données, sur deux supports différents, dont une hors site. Testez de temps en temps qu'une restauration fonctionne vraiment."],
   "tips": ["Sauvegardez au moins chaque semaine, chaque jour pour un usage professionnel.", "Débranchez le disque de sauvegarde après usage.", "Gardez une copie ailleurs (autre lieu ou service en ligne).", "Testez la restauration d'un fichier une fois par trimestre."]},
  {"id": "downloads", "title": "N'installez que depuis des sources officielles", "summary": "Un « installateur gratuit » trouvé sur un site inconnu est le vecteur numéro un des chevaux de Troie.",
   "details": ["Les logiciels piratés, les « cracks », les faux lecteurs vidéo et les extensions douteuses embarquent très souvent un programme espion. Sur Linux Mint, passez par le Gestionnaire de logiciels, les dépôts officiels ou Flathub, et vérifiez qu'un .deb téléchargé vient bien du site de l'éditeur.", "Cette application signale les programmes qui n'appartiennent à aucun paquet et qui modifient vos fichiers ou se connectent à Internet : c'est précisément pour repérer ce genre d'installation."],
   "tips": ["Gestionnaire de logiciels, dépôts officiels, Flathub : rien d'autre sans vérification.", "Un logiciel payant « gratuit » est presque toujours piégé.", "Vérifiez la signature ou l'empreinte d'un fichier téléchargé quand l'éditeur la fournit.", "Ne lancez pas un script « curl … | bash » trouvé sur un forum sans le comprendre."]},
  {"id": "fake_support", "title": "Faux support technique et fausses alertes", "summary": "« Votre ordinateur est infecté, appelez ce numéro » : une page web ne peut pas savoir cela. C'est une arnaque.",
   "details": ["Une fenêtre plein écran, une alarme sonore, un logo Microsoft ou Apple, un numéro à appeler : ces pages veulent que vous installiez un logiciel de prise de contrôle à distance ou que vous payiez une « réparation ». Le vrai support ne vous appelle jamais spontanément et n'affiche pas d'alertes dans le navigateur.", "Fermez l'onglet ou le navigateur (au besoin avec Ctrl+Alt+Suppr ou en redémarrant). Rien n'est infecté tant que vous n'avez rien installé ni donné accès."],
   "tips": ["N'appelez jamais un numéro affiché par une alerte web.", "N'installez jamais un logiciel de contrôle à distance à la demande d'un inconnu.", "Fermez la page ; si elle bloque, fermez le navigateur.", "Les seules alertes fiables sont celles de cette application et du système, jamais d'une page web."]},
  {"id": "phone_scam", "title": "Manipulation par téléphone (ingénierie sociale)", "summary": "Un « conseiller » de votre banque, de la police ou d'un fournisseur vous appelle et vous presse : raccrochez et rappelez le vrai numéro.",
   "details": ["L'ingénierie sociale exploite la confiance et la peur, pas la technique. Le numéro affiché peut être usurpé, l'interlocuteur connaît votre nom et votre adresse (souvent publics) et invente un scénario crédible : compte piraté, paiement suspect, colis bloqué, proche en difficulté.", "Un vrai employé ne vous demandera jamais un mot de passe, un code SMS, un virement vers un « compte sécurisé » ni d'installer un programme. Toute urgence imposée par téléphone est suspecte."],
   "tips": ["Raccrochez et rappelez avec le numéro officiel figurant sur votre carte ou le site.", "Ne donnez jamais de code ou de mot de passe par téléphone.", "Refusez toute installation de logiciel demandée à distance.", "Parlez-en à un proche avant d'agir : l'isolement fait partie de la manipulation."]},
  {"id": "wifi", "title": "Wi-Fi public et réseaux inconnus", "summary": "Sur un réseau que vous ne contrôlez pas, quelqu'un peut observer ou détourner votre trafic.",
   "details": ["Dans un café, un hôtel ou une gare, le réseau « Free_WiFi » peut être tenu par un pirate. Les sites en https protègent le contenu, mais les portails de connexion piégés, les fausses mises à jour et les partages de fichiers ouverts restent des risques.", "Le pare-feu activé et l'accès à distance (SSH) désactivé, comme le recommande cette application, réduisent ce que votre ordinateur expose aux autres membres du réseau."],
   "tips": ["Préférez le partage de connexion de votre téléphone à un Wi-Fi inconnu.", "Utilisez un VPN de confiance sur les réseaux publics.", "N'acceptez aucune « mise à jour » proposée par un portail Wi-Fi.", "Gardez le pare-feu actif et les partages de fichiers désactivés."]},
  {"id": "sudo", "title": "Le mot de passe administrateur n'est pas un simple « OK »", "summary": "Quand un programme demande votre mot de passe, il obtient tous les droits sur l'ordinateur. Demandez-vous pourquoi.",
   "details": ["Sous Linux, votre mot de passe (sudo, pkexec) donne le contrôle total : installation de logiciels, lecture de tous les fichiers, modification du système. Un cheval de Troie qui obtient ce mot de passe peut désactiver l'antivirus et le pare-feu.", "Saisissez-le uniquement pour une action que vous avez déclenchée vous-même et que vous comprenez : mise à jour, installation depuis une source officielle, réglage système. Une demande surprise, surtout après avoir ouvert un fichier reçu, est un signal d'alarme."],
   "tips": ["Ne saisissez votre mot de passe que pour une action que vous avez lancée.", "Lisez le texte de la fenêtre : quel programme demande quoi ?", "Ne travaillez jamais en permanence avec le compte root.", "Cette application demande ce mot de passe seulement pour désactiver le pare-feu, ouvrir un port, activer SSH ou installer une mise à jour."]},
  {"id": "ransomware_response", "title": "Que faire en cas d'attaque ?", "summary": "Débranchez, ne payez pas, prévenez, restaurez : les bons gestes limitent les dégâts.",
   "details": ["Si des fichiers changent de nom, deviennent illisibles ou qu'une demande de rançon apparaît : coupez immédiatement le réseau (Wi-Fi, câble) et éteignez les autres appareils connectés au même réseau. Ne payez pas : rien ne garantit la clé, et vous financez la prochaine attaque.", "Prévenez votre responsable informatique ou un professionnel, conservez les preuves (photos de l'écran, messages) et déposez plainte. Réinstallez le système proprement puis restaurez vos sauvegardes hors ligne. Changez ensuite tous vos mots de passe depuis un appareil sain."],
   "tips": ["Déconnecter d'abord, réfléchir ensuite.", "Ne payez pas la rançon.", "Signalez l'incident (police, cybercrime.admin.ch en Suisse).", "Réinstallez proprement et restaurez depuis une sauvegarde saine."]},
  {"id": "extensions", "title": "Extensions de navigateur et permissions", "summary": "Une extension peut lire tout ce que vous voyez et tapez dans le navigateur. Installez-en le moins possible.",
   "details": ["Les extensions demandent souvent « lire et modifier toutes les données des sites web » : c'est exactement ce dont a besoin un espion pour voler mots de passe et numéros de carte. Des extensions honnêtes sont parfois rachetées puis transformées en logiciels malveillants lors d'une mise à jour.", "Cette application liste vos extensions et signale celles qui ne viennent pas d'un store officiel. Faites le tri régulièrement."],
   "tips": ["N'installez que des extensions connues, depuis le store officiel, avec de nombreux utilisateurs.", "Supprimez celles que vous n'utilisez plus.", "Refusez les extensions proposées par un site ou une publicité.", "Vérifiez les permissions demandées : une « météo » n'a pas besoin de lire vos e-mails."]}
],
"en": [
  {"id": "click", "title": "Never click without reading", "summary": "Most attacks start with a reflex click on a link, an attachment or an “OK” button.",
   "details": ["Attackers rely on haste: an alarming message (“your account will be closed”), a limited offer, a parcel waiting. Take three seconds to read the sender's address, hover over the link to see where it really leads and ask yourself whether you were expecting this message.", "A link can display “www.mybank.ch” and point to a completely different site. On a computer, hover over the link: the real destination appears at the bottom of the window. On a phone, long-press to see it."],
   "tips": ["Read the sender's full address, not just the displayed name.", "Hover over links before clicking; when in doubt, type the site address yourself.", "No bank, authority or serious service asks for a password by e-mail.", "A message that rushes you is a warning sign, not an emergency."]},
  {"id": "phishing", "title": "Recognising phishing", "summary": "A fake message imitates a well-known company to make you enter your credentials or card number.",
   "details": ["Phishing comes as e-mails, text messages (“smishing”), WhatsApp messages or calls. The message copies the logo and style of a bank, the post office, a telecom operator, the tax office, Amazon… and sends you to a login page that is a copy. Everything you type there goes straight to the attacker.", "Classic clues: an approximate sender address (support@swiss-post-secure.com), spelling mistakes or odd wording, a generic greeting (“Dear customer”), a request to pay a small amount (customs fee of CHF 2.90), a threat of blocking."],
   "tips": ["Never log in from a received link: open the app or type the official address.", "Compare the site address with the one you usually use, letter by letter.", "Report the message to the imitated company and delete it.", "If you entered a password on a fake site, change it immediately everywhere it is used."]},
  {"id": "ceo_fraud", "title": "Hacked management: CEO fraud", "summary": "An e-mail apparently from your boss or a colleague asks for an urgent transfer or confidential data.",
   "details": ["Attackers study the company (website, LinkedIn) and then send a very plausible message: “I'm in a meeting, make this CHF 12,000 transfer before noon, I'll explain later.” Sometimes the executive's mailbox has really been hacked, which makes the message look authentic.", "The lever is always the same: authority, urgency and secrecy (“don't tell anyone”). No normal procedure works like this."],
   "tips": ["Any request for a transfer, an IBAN change or sensitive data is confirmed by phone, using a number you already know.", "Beware of urgency and secrecy: they are the signature of the scam.", "A legitimate sender address proves nothing if the account has been hacked.", "Apply the four-eyes rule for payments."]},
  {"id": "unusual_mail", "title": "An unusual e-mail? Check through another channel", "summary": "A known contact writing differently, at an odd hour, with an unexpected attachment: don't reply in the thread.",
   "details": ["When an e-mail account is hacked, the attacker sends messages to all contacts, often as replies to real past conversations. The tone, language or signature may change slightly, and the attachment is a “document” or “invoice” nobody was expecting.", "The right reflex is to verify through another channel: a call, a text message, a face-to-face conversation. Don't reply to the message itself — the attacker reads the replies."],
   "tips": ["Compare the style: wording, language, signature, sending time.", "Don't open an attachment you weren't expecting, even from a friend.", "Call the person to confirm before opening or paying.", "Warn your contact if you think their account is hacked."]},
  {"id": "double_ext", "title": "salaries.xlsx.exe: the double extension trap", "summary": "A file named “salaries.xlsx.exe” or “invoice.pdf.sh” is not a spreadsheet or a PDF: it is a program.",
   "details": ["The system only looks at the last extension. “salaries.xlsx.exe” is a Windows executable, “report.pdf.sh” a Linux script, “photo.jpg.desktop” a launcher. By double-clicking you run an unknown program with your rights: it can encrypt your documents or steal your passwords.", "Dangerous extensions on Linux include .sh, .run, .bin, .desktop, .AppImage, .py, .pl and .deb from unknown sources. On Windows: .exe, .scr, .bat, .cmd, .js, .vbs, .msi. The system may also hide known extensions, which is why you should display them."],
   "tips": ["Always show file extensions in the file manager.", "A document should never have two extensions.", "Never run a file received by e-mail or messaging without scanning it and checking with the sender.", "On Linux a file only runs if you give it permission: don't do it for an unknown file."]},
  {"id": "usb", "title": "USB sticks: found, gifted… or booby-trapped", "summary": "A stick found in a car park or received as a gift may contain a trojan, or even pretend to be a keyboard.",
   "details": ["Attackers deliberately drop infected sticks near companies: curiosity does the rest. Some “BadUSB” sticks present themselves as a keyboard and type commands on your behalf in seconds, with no visible file.", "ClamAV Antivirus GUI scans USB sticks before opening them, but that does not protect against a keyboard-stick or a program you launch yourself. A stick of unknown origin does not get plugged in."],
   "tips": ["Never plug in a USB stick whose origin you don't know.", "Let the automatic scan finish before opening files.", "Don't run any program from a stick; only copy documents.", "To exchange files, prefer online sharing or encrypted transfer."]},
  {"id": "malware_types", "title": "Virus, worm, trojan, cryptolocker: the differences", "summary": "All are malicious software, but they don't enter or act the same way.",
   "details": ["A virus attaches itself to a program or document and spreads when it is opened. A worm spreads by itself from computer to computer over the network by exploiting a vulnerability, with no human action. A trojan horse poses as useful software (game, utility, “video player”) but opens a back door: password theft, webcam spying, remote control.", "A cryptolocker (ransomware) encrypts your files and demands a ransom for the key. It often arrives through an attachment or a trojan. Without a backup the data is usually lost, and paying guarantees nothing."],
   "tips": ["The trojan is the most common today: beware of “free” software outside official sources.", "A worm exploits vulnerabilities: updates are your protection.", "Against a cryptolocker only an offline backup saves you.", "Antivirus detects known threats; new ones sometimes slip through."]},
  {"id": "vulnerability", "title": "What is a security vulnerability?", "summary": "A mistake in a program that lets an attacker do what they should not be able to do.",
   "details": ["Software contains millions of lines of code written by humans. Some mistakes let an attacker crash the program, inject commands or take control of the machine simply by opening a crafted image, web page or document. Each known vulnerability gets a CVE number (for example CVE-2026-63072).", "Between the publication of a vulnerability and its fix, attackers automate attacks on every computer that is not updated. The Security tab of this application shows the known vulnerabilities of installed programs and whether a fix exists."],
   "tips": ["A “critical” or “high” vulnerability without a fix is a reason to uninstall or stop using the program.", "The less software you have installed, the fewer vulnerabilities you have.", "Browsers and document readers are the most exposed: keep them up to date.", "A vulnerability is not an infection; it is an unlocked door."]},
  {"id": "updates", "title": "Why updates are vital", "summary": "Security updates close the vulnerabilities attackers are already exploiting.",
   "details": ["A security update brings no visible novelty: it fixes a vulnerability. Once the fix is published, the vulnerability is known to everyone, including attackers, who target machines that lag behind. A computer not updated for months is an easy target.", "On Linux Mint, the Update Manager and this application show security (red), recommended (applications) and phased updates. Reboot when asked: some fixes (kernel) are only active afterwards."],
   "tips": ["Install security updates as soon as they appear.", "Enable automatic updates if you often forget.", "Also update Flatpak apps, browser extensions and firmware.", "Software no longer updated by its publisher must be replaced."]},
  {"id": "passwords", "title": "Passwords and two-factor authentication", "summary": "One long, unique password per service, plus a second verification: that is the foundation.",
   "details": ["When a site is hacked, the stolen passwords are automatically tested on hundreds of other services. Reusing the same password is like handing out a key that opens all your doors. Length matters more than complexity: a four- or five-word phrase is safer than “P@ssw0rd!”.", "A password manager (Bitwarden, KeePassXC…) creates and remembers unique passwords for you. Two-factor authentication (app code, security key) blocks an attacker even if they know the password."],
   "tips": ["A different password for each service, managed by a password manager.", "Enable two-factor authentication on e-mail, banking and social networks first.", "Never share a code received by text message, even with an “advisor”.", "Check haveibeenpwned.com to see whether your address appears in a leak."]},
  {"id": "backups", "title": "Backups: your insurance against everything", "summary": "Against ransomware, a failure or theft, only a recent offline backup saves you.",
   "details": ["A useful backup is automatic, regular and disconnected: an external disk you plug in and then unplug, or an online service with versioning. A disk that stays connected will be encrypted together with the computer by a cryptolocker.", "The 3-2-1 rule: three copies of your data, on two different media, one of them off-site. Test from time to time that a restore really works."],
   "tips": ["Back up at least weekly, daily for professional use.", "Unplug the backup disk after use.", "Keep a copy elsewhere (another place or an online service).", "Test restoring a file once a quarter."]},
  {"id": "downloads", "title": "Install only from official sources", "summary": "A “free installer” found on an unknown site is the number one vector for trojans.",
   "details": ["Pirated software, “cracks”, fake video players and dubious extensions very often carry spyware. On Linux Mint, use the Software Manager, the official repositories or Flathub, and check that a downloaded .deb really comes from the publisher's site.", "This application flags programs that belong to no package and that modify your files or connect to the Internet: precisely to spot this kind of installation."],
   "tips": ["Software Manager, official repositories, Flathub: nothing else without verification.", "A paid program offered “for free” is almost always booby-trapped.", "Verify the signature or checksum of a download when the publisher provides one.", "Don't run a “curl … | bash” script found on a forum without understanding it."]},
  {"id": "fake_support", "title": "Fake tech support and fake alerts", "summary": "“Your computer is infected, call this number”: a web page cannot know that. It's a scam.",
   "details": ["A full-screen window, an alarm sound, a Microsoft or Apple logo, a number to call: these pages want you to install remote-control software or pay for a “repair”. Real support never calls you spontaneously and never shows alerts in the browser.", "Close the tab or the browser (with Ctrl+Alt+Del or a reboot if needed). Nothing is infected as long as you haven't installed anything or granted access."],
   "tips": ["Never call a number shown by a web alert.", "Never install remote-control software at a stranger's request.", "Close the page; if it blocks, close the browser.", "The only reliable alerts come from this application and the system, never from a web page."]},
  {"id": "phone_scam", "title": "Phone manipulation (social engineering)", "summary": "An “advisor” from your bank, the police or a provider calls and pressures you: hang up and call back the real number.",
   "details": ["Social engineering exploits trust and fear, not technology. The displayed number can be spoofed, the caller knows your name and address (often public) and invents a credible scenario: hacked account, suspicious payment, blocked parcel, relative in trouble.", "A real employee will never ask for a password, a text-message code, a transfer to a “safe account” or the installation of a program. Any urgency imposed by phone is suspicious."],
   "tips": ["Hang up and call back using the official number on your card or the website.", "Never give a code or password by phone.", "Refuse any software installation requested remotely.", "Talk to someone close before acting: isolation is part of the manipulation."]},
  {"id": "wifi", "title": "Public Wi-Fi and unknown networks", "summary": "On a network you don't control, someone can observe or hijack your traffic.",
   "details": ["In a café, a hotel or a station, the “Free_WiFi” network may be run by an attacker. https sites protect the content, but booby-trapped login portals, fake updates and open file shares remain risks.", "An active firewall and disabled remote access (SSH), as this application recommends, reduce what your computer exposes to other members of the network."],
   "tips": ["Prefer your phone's hotspot to an unknown Wi-Fi.", "Use a trusted VPN on public networks.", "Never accept an “update” offered by a Wi-Fi portal.", "Keep the firewall on and file sharing off."]},
  {"id": "sudo", "title": "The administrator password is not a simple “OK”", "summary": "When a program asks for your password, it gets full rights on the computer. Ask yourself why.",
   "details": ["On Linux, your password (sudo, pkexec) grants full control: installing software, reading every file, modifying the system. A trojan that obtains this password can disable the antivirus and the firewall.", "Enter it only for an action you triggered yourself and understand: an update, an installation from an official source, a system setting. A surprise request, especially after opening a received file, is an alarm signal."],
   "tips": ["Only enter your password for an action you started.", "Read the dialog text: which program asks for what?", "Never work permanently with the root account.", "This application asks for this password only to disable the firewall, open a port, enable SSH or install an update."]},
  {"id": "ransomware_response", "title": "What to do in case of an attack?", "summary": "Disconnect, don't pay, report, restore: the right moves limit the damage.",
   "details": ["If files change names, become unreadable or a ransom note appears: cut the network immediately (Wi-Fi, cable) and switch off the other devices on the same network. Don't pay: nothing guarantees the key, and you fund the next attack.", "Inform your IT manager or a professional, keep the evidence (screen photos, messages) and file a complaint. Reinstall the system cleanly and then restore your offline backups. Then change all your passwords from a clean device."],
   "tips": ["Disconnect first, think afterwards.", "Don't pay the ransom.", "Report the incident (police, cybercrime.admin.ch in Switzerland).", "Reinstall cleanly and restore from a clean backup."]},
  {"id": "extensions", "title": "Browser extensions and permissions", "summary": "An extension can read everything you see and type in the browser. Install as few as possible.",
   "details": ["Extensions often ask to “read and change all your data on websites”: exactly what a spy needs to steal passwords and card numbers. Honest extensions are sometimes bought and turned into malware in an update.", "This application lists your extensions and flags those that don't come from an official store. Sort them out regularly."],
   "tips": ["Install only well-known extensions, from the official store, with many users.", "Remove those you no longer use.", "Refuse extensions offered by a site or an advert.", "Check the requested permissions: a “weather” extension doesn't need to read your e-mails."]}
],
"de": [
  {"id": "click", "title": "Nie klicken, ohne zu lesen", "summary": "Die meisten Angriffe beginnen mit einem Reflexklick auf einen Link, einen Anhang oder eine „OK“-Schaltfläche.",
   "details": ["Angreifer setzen auf Eile: eine alarmierende Nachricht („Ihr Konto wird geschlossen“), ein befristetes Angebot, ein wartendes Paket. Nehmen Sie sich drei Sekunden: Absenderadresse lesen, mit der Maus über den Link fahren, um das wahre Ziel zu sehen, und sich fragen, ob Sie diese Nachricht erwartet haben.", "Ein Link kann „www.meinebank.ch“ anzeigen und auf eine ganz andere Website führen. Am Computer erscheint das echte Ziel unten im Fenster, wenn Sie über den Link fahren. Am Telefon lange drücken, um es zu sehen."],
   "tips": ["Lesen Sie die vollständige Absenderadresse, nicht nur den angezeigten Namen.", "Fahren Sie vor dem Klicken über Links; im Zweifel die Adresse selbst eintippen.", "Keine Bank, Behörde oder seriöse Firma fragt per E-Mail nach einem Passwort.", "Eine Nachricht, die Sie drängt, ist ein Warnsignal, kein Notfall."]},
  {"id": "phishing", "title": "Phishing erkennen", "summary": "Eine gefälschte Nachricht ahmt ein bekanntes Unternehmen nach, damit Sie Zugangsdaten oder Kartennummer eingeben.",
   "details": ["Phishing kommt als E-Mail, SMS („Smishing“), WhatsApp-Nachricht oder Anruf. Die Nachricht kopiert Logo und Stil einer Bank, der Post, der Swisscom, der Steuerverwaltung, von Amazon … und leitet auf eine Anmeldeseite, die eine Kopie ist. Alles, was Sie dort eingeben, geht direkt an den Angreifer.", "Klassische Hinweise: ungefähre Absenderadresse (support@swiss-post-secure.com), Fehler oder seltsame Formulierungen, allgemeine Anrede („Sehr geehrter Kunde“), Bitte um eine kleine Zahlung (Zollgebühr CHF 2.90), Drohung mit Sperrung."],
   "tips": ["Melden Sie sich nie über einen erhaltenen Link an: App öffnen oder offizielle Adresse eintippen.", "Vergleichen Sie die Adresse Buchstabe für Buchstabe mit der gewohnten.", "Melden Sie die Nachricht dem nachgeahmten Unternehmen und löschen Sie sie.", "Haben Sie ein Passwort auf einer gefälschten Seite eingegeben, ändern Sie es sofort überall."]},
  {"id": "ceo_fraud", "title": "Gehackte Geschäftsleitung: CEO-Betrug", "summary": "Eine E-Mail scheinbar vom Chef oder einem Kollegen verlangt eine dringende Überweisung oder vertrauliche Daten.",
   "details": ["Angreifer studieren das Unternehmen (Website, LinkedIn) und senden dann eine sehr plausible Nachricht: „Ich bin in einer Sitzung, überweise die CHF 12'000 vor Mittag, ich erkläre es später.“ Manchmal wurde das Postfach der Führungskraft tatsächlich gehackt, was die Nachricht echt wirken lässt.", "Der Hebel ist immer derselbe: Autorität, Dringlichkeit und Geheimhaltung („sag es niemandem“). Kein normales Verfahren funktioniert so."],
   "tips": ["Jede Überweisung, IBAN-Änderung oder Weitergabe sensibler Daten wird telefonisch bestätigt – mit einer Nummer, die Sie bereits kennen.", "Misstrauen Sie Dringlichkeit und Geheimhaltung: Sie sind die Handschrift des Betrugs.", "Eine legitime Absenderadresse beweist nichts, wenn das Konto gehackt wurde.", "Führen Sie das Vier-Augen-Prinzip für Zahlungen ein."]},
  {"id": "unusual_mail", "title": "Ungewöhnliche E-Mail? Über einen anderen Kanal prüfen", "summary": "Ein bekannter Kontakt, der anders schreibt, zu seltsamer Zeit, mit unerwartetem Anhang: nicht im Verlauf antworten.",
   "details": ["Wird ein E-Mail-Konto gehackt, schickt der Angreifer Nachrichten an alle Kontakte, oft als Antwort auf echte frühere Gespräche. Ton, Sprache oder Signatur ändern sich leicht, der Anhang ist ein „Dokument“ oder eine „Rechnung“, die niemand erwartet hat.", "Der richtige Reflex: über einen anderen Kanal prüfen – Anruf, SMS, persönliches Gespräch. Antworten Sie nicht auf die Nachricht selbst, der Angreifer liest die Antworten."],
   "tips": ["Vergleichen Sie den Stil: Formulierungen, Sprache, Signatur, Sendezeit.", "Öffnen Sie keinen unerwarteten Anhang, auch nicht von Bekannten.", "Rufen Sie die Person an, bevor Sie öffnen oder zahlen.", "Warnen Sie Ihren Kontakt, wenn Sie glauben, dass sein Konto gehackt ist."]},
  {"id": "double_ext", "title": "loehne.xlsx.exe: die Falle der doppelten Endung", "summary": "Eine Datei namens „loehne.xlsx.exe“ oder „rechnung.pdf.sh“ ist keine Tabelle und kein PDF: es ist ein Programm.",
   "details": ["Das System beachtet nur die letzte Endung. „loehne.xlsx.exe“ ist ein Windows-Programm, „bericht.pdf.sh“ ein Linux-Skript, „foto.jpg.desktop“ ein Starter. Mit einem Doppelklick führen Sie ein unbekanntes Programm mit Ihren Rechten aus: Es kann Ihre Dokumente verschlüsseln oder Passwörter stehlen.", "Gefährliche Endungen unter Linux sind u. a. .sh, .run, .bin, .desktop, .AppImage, .py, .pl und .deb aus unbekannter Quelle. Unter Windows: .exe, .scr, .bat, .cmd, .js, .vbs, .msi. Das System kann bekannte Endungen auch ausblenden – deshalb sollten Sie sie anzeigen lassen."],
   "tips": ["Lassen Sie Dateiendungen im Dateimanager immer anzeigen.", "Ein Dokument sollte nie zwei Endungen haben.", "Führen Sie nie eine per E-Mail oder Messenger erhaltene Datei aus, ohne sie zu prüfen und beim Absender nachzufragen.", "Unter Linux läuft eine Datei nur, wenn Sie ihr das Recht geben: tun Sie das nicht bei unbekannten Dateien."]},
  {"id": "usb", "title": "USB-Sticks: gefunden, geschenkt … oder präpariert", "summary": "Ein auf dem Parkplatz gefundener oder geschenkter Stick kann einen Trojaner enthalten oder sich als Tastatur ausgeben.",
   "details": ["Angreifer legen absichtlich infizierte Sticks in der Nähe von Firmen ab: Die Neugier erledigt den Rest. Manche „BadUSB“-Sticks melden sich als Tastatur und tippen in Sekunden Befehle an Ihrer Stelle, ohne dass eine Datei sichtbar wäre.", "ClamAV Antivirus GUI prüft USB-Sticks vor dem Öffnen, schützt aber weder vor einem Tastatur-Stick noch vor einem Programm, das Sie selbst starten. Ein Stick unbekannter Herkunft wird nicht eingesteckt."],
   "tips": ["Stecken Sie nie einen USB-Stick ein, dessen Herkunft Sie nicht kennen.", "Lassen Sie die automatische Prüfung beenden, bevor Sie Dateien öffnen.", "Starten Sie kein Programm vom Stick, kopieren Sie nur Dokumente.", "Zum Datenaustausch lieber Online-Freigabe oder verschlüsselter Versand."]},
  {"id": "malware_types", "title": "Virus, Wurm, Trojaner, Cryptolocker: die Unterschiede", "summary": "Alle sind Schadsoftware, aber sie gelangen nicht gleich hinein und handeln nicht gleich.",
   "details": ["Ein Virus hängt sich an ein Programm oder Dokument und verbreitet sich beim Öffnen. Ein Wurm verbreitet sich von selbst über das Netzwerk von Rechner zu Rechner, indem er eine Schwachstelle ausnutzt – ohne menschliches Zutun. Ein Trojaner gibt sich als nützliche Software aus (Spiel, Werkzeug, „Videoplayer“), öffnet aber eine Hintertür: Passwortdiebstahl, Webcam-Spionage, Fernsteuerung.", "Ein Cryptolocker (Ransomware) verschlüsselt Ihre Dateien und verlangt Lösegeld für den Schlüssel. Er kommt oft über einen Anhang oder einen Trojaner. Ohne Backup sind die Daten meist verloren, und Zahlen garantiert nichts."],
   "tips": ["Der Trojaner ist heute am häufigsten: Vorsicht bei „kostenloser“ Software außerhalb offizieller Quellen.", "Ein Wurm nutzt Schwachstellen: Updates sind Ihr Schutz.", "Gegen einen Cryptolocker rettet Sie nur ein Offline-Backup.", "Der Virenschutz erkennt bekannte Bedrohungen; neue schlüpfen manchmal durch."]},
  {"id": "vulnerability", "title": "Was ist eine Sicherheitslücke?", "summary": "Ein Fehler in einem Programm, der einem Angreifer erlaubt, was er nicht können sollte.",
   "details": ["Software besteht aus Millionen von Menschen geschriebener Codezeilen. Manche Fehler erlauben es, das Programm abstürzen zu lassen, Befehle einzuschleusen oder den Rechner zu übernehmen – allein durch das Öffnen eines präparierten Bildes, einer Webseite oder eines Dokuments. Jede bekannte Lücke erhält eine CVE-Nummer (z. B. CVE-2026-63072).", "Zwischen Veröffentlichung einer Lücke und ihrer Behebung automatisieren Angreifer den Angriff auf alle nicht aktualisierten Rechner. Der Reiter Sicherheit dieser Anwendung zeigt die bekannten Lücken der installierten Programme und ob eine Korrektur existiert."],
   "tips": ["Eine „kritische“ oder „hohe“ Lücke ohne Korrektur ist ein Grund, das Programm zu deinstallieren oder nicht zu nutzen.", "Je weniger Software installiert ist, desto weniger Lücken.", "Browser und Dokumentenleser sind am stärksten exponiert: aktuell halten.", "Eine Lücke ist keine Infektion; sie ist eine unverschlossene Tür."]},
  {"id": "updates", "title": "Warum Updates lebenswichtig sind", "summary": "Sicherheitsupdates schließen Lücken, die Angreifer bereits ausnutzen.",
   "details": ["Ein Sicherheitsupdate bringt nichts sichtbar Neues: Es behebt eine Lücke. Sobald die Korrektur veröffentlicht ist, kennt jeder die Lücke – auch Angreifer, die auf verzögerte Rechner zielen. Ein monatelang nicht aktualisierter Computer ist ein leichtes Ziel.", "Unter Linux Mint zeigen die Aktualisierungsverwaltung und diese Anwendung Sicherheits- (rot), empfohlene (Anwendungen) und gestaffelte Updates. Starten Sie neu, wenn Sie dazu aufgefordert werden: Manche Korrekturen (Kernel) wirken erst danach."],
   "tips": ["Installieren Sie Sicherheitsupdates, sobald sie erscheinen.", "Aktivieren Sie automatische Updates, wenn Sie es oft vergessen.", "Aktualisieren Sie auch Flatpak-Apps, Browser-Erweiterungen und Firmware.", "Software, die vom Hersteller nicht mehr gepflegt wird, muss ersetzt werden."]},
  {"id": "passwords", "title": "Passwörter und Zwei-Faktor-Authentifizierung", "summary": "Ein langes, einzigartiges Passwort pro Dienst plus eine zweite Bestätigung: das ist die Basis.",
   "details": ["Wird eine Website gehackt, werden die gestohlenen Passwörter automatisch bei Hunderten anderer Dienste ausprobiert. Dasselbe Passwort wiederzuverwenden heißt, einen Schlüssel zu verteilen, der alle Ihre Türen öffnet. Länge zählt mehr als Komplexität: Ein Satz aus vier oder fünf Wörtern ist sicherer als „P@ssw0rd!“.", "Ein Passwortmanager (Bitwarden, KeePassXC …) erstellt und merkt sich einzigartige Passwörter für Sie. Die Zwei-Faktor-Authentifizierung (App-Code, Sicherheitsschlüssel) stoppt einen Angreifer selbst dann, wenn er das Passwort kennt."],
   "tips": ["Für jeden Dienst ein anderes Passwort, verwaltet von einem Passwortmanager.", "Aktivieren Sie 2FA zuerst bei E-Mail, Bank und sozialen Netzwerken.", "Geben Sie nie einen per SMS erhaltenen Code weiter, auch nicht an einen „Berater“.", "Prüfen Sie auf haveibeenpwned.com, ob Ihre Adresse in einem Datenleck auftaucht."]},
  {"id": "backups", "title": "Backups: Ihre Versicherung gegen alles", "summary": "Bei Ransomware, Defekt oder Diebstahl rettet Sie nur ein aktuelles Offline-Backup.",
   "details": ["Ein nützliches Backup ist automatisch, regelmäßig und getrennt: eine externe Festplatte, die Sie anschließen und wieder abziehen, oder ein Online-Dienst mit Versionierung. Eine dauerhaft angeschlossene Festplatte wird von einem Cryptolocker zusammen mit dem Rechner verschlüsselt.", "3-2-1-Regel: drei Kopien Ihrer Daten, auf zwei verschiedenen Medien, eine davon außer Haus. Testen Sie gelegentlich, ob eine Wiederherstellung wirklich funktioniert."],
   "tips": ["Mindestens wöchentlich sichern, beruflich täglich.", "Backup-Festplatte nach Gebrauch abziehen.", "Eine Kopie andernorts aufbewahren (anderer Ort oder Online-Dienst).", "Einmal pro Quartal die Wiederherstellung einer Datei testen."]},
  {"id": "downloads", "title": "Nur aus offiziellen Quellen installieren", "summary": "Ein „kostenloser Installer“ von einer unbekannten Website ist der Trojaner-Vektor Nummer eins.",
   "details": ["Raubkopien, „Cracks“, falsche Videoplayer und zweifelhafte Erweiterungen bringen sehr oft Spionagesoftware mit. Nutzen Sie unter Linux Mint die Anwendungsverwaltung, die offiziellen Repositories oder Flathub, und prüfen Sie, dass ein heruntergeladenes .deb wirklich von der Herstellerseite stammt.", "Diese Anwendung meldet Programme, die zu keinem Paket gehören und Ihre Dateien ändern oder sich mit dem Internet verbinden – genau um solche Installationen zu erkennen."],
   "tips": ["Anwendungsverwaltung, offizielle Repositories, Flathub: nichts anderes ohne Prüfung.", "Ein kostenpflichtiges Programm „gratis“ ist fast immer präpariert.", "Prüfen Sie Signatur oder Prüfsumme eines Downloads, wenn der Hersteller sie bereitstellt.", "Führen Sie kein „curl … | bash“ aus einem Forum aus, ohne es zu verstehen."]},
  {"id": "fake_support", "title": "Falscher technischer Support und falsche Warnungen", "summary": "„Ihr Computer ist infiziert, rufen Sie diese Nummer an“: Das kann eine Webseite nicht wissen. Es ist Betrug.",
   "details": ["Ein Vollbildfenster, ein Alarmton, ein Microsoft- oder Apple-Logo, eine Telefonnummer: Diese Seiten wollen, dass Sie Fernwartungssoftware installieren oder eine „Reparatur“ bezahlen. Echter Support ruft nie unaufgefordert an und zeigt keine Warnungen im Browser.", "Schließen Sie den Tab oder den Browser (notfalls mit Strg+Alt+Entf oder einem Neustart). Nichts ist infiziert, solange Sie nichts installiert oder freigegeben haben."],
   "tips": ["Rufen Sie nie eine von einer Web-Warnung angezeigte Nummer an.", "Installieren Sie nie Fernwartungssoftware auf Wunsch eines Fremden.", "Schließen Sie die Seite; wenn sie blockiert, den Browser.", "Verlässliche Warnungen kommen nur von dieser Anwendung und vom System, nie von einer Webseite."]},
  {"id": "phone_scam", "title": "Manipulation am Telefon (Social Engineering)", "summary": "Ein „Berater“ Ihrer Bank, der Polizei oder eines Anbieters ruft an und drängt: auflegen und die echte Nummer zurückrufen.",
   "details": ["Social Engineering nutzt Vertrauen und Angst, nicht Technik. Die angezeigte Nummer kann gefälscht sein, der Anrufer kennt Ihren Namen und Ihre Adresse (oft öffentlich) und erfindet ein glaubwürdiges Szenario: gehacktes Konto, verdächtige Zahlung, blockiertes Paket, Angehöriger in Not.", "Ein echter Mitarbeiter verlangt nie ein Passwort, einen SMS-Code, eine Überweisung auf ein „Sicherheitskonto“ oder die Installation eines Programms. Jede am Telefon erzeugte Dringlichkeit ist verdächtig."],
   "tips": ["Auflegen und mit der offiziellen Nummer von Karte oder Website zurückrufen.", "Nie einen Code oder ein Passwort am Telefon nennen.", "Jede aus der Ferne verlangte Softwareinstallation ablehnen.", "Sprechen Sie mit einer vertrauten Person, bevor Sie handeln: Isolation ist Teil der Manipulation."]},
  {"id": "wifi", "title": "Öffentliches WLAN und unbekannte Netzwerke", "summary": "In einem Netzwerk, das Sie nicht kontrollieren, kann jemand Ihren Datenverkehr beobachten oder umleiten.",
   "details": ["Im Café, Hotel oder Bahnhof kann das Netz „Free_WiFi“ von einem Angreifer betrieben werden. https-Seiten schützen den Inhalt, aber präparierte Anmeldeportale, falsche Updates und offene Dateifreigaben bleiben Risiken.", "Eine aktive Firewall und deaktivierter Fernzugriff (SSH), wie von dieser Anwendung empfohlen, verringern, was Ihr Rechner den anderen Teilnehmern des Netzwerks zeigt."],
   "tips": ["Bevorzugen Sie den Hotspot Ihres Telefons gegenüber unbekanntem WLAN.", "Nutzen Sie in öffentlichen Netzen ein vertrauenswürdiges VPN.", "Akzeptieren Sie kein „Update“, das ein WLAN-Portal anbietet.", "Firewall an, Dateifreigaben aus."]},
  {"id": "sudo", "title": "Das Administratorpasswort ist kein einfaches „OK“", "summary": "Fragt ein Programm nach Ihrem Passwort, erhält es alle Rechte auf dem Rechner. Fragen Sie sich, warum.",
   "details": ["Unter Linux gibt Ihr Passwort (sudo, pkexec) die volle Kontrolle: Software installieren, alle Dateien lesen, das System verändern. Ein Trojaner, der dieses Passwort erhält, kann Virenschutz und Firewall abschalten.", "Geben Sie es nur für eine Aktion ein, die Sie selbst ausgelöst haben und verstehen: Update, Installation aus offizieller Quelle, Systemeinstellung. Eine überraschende Abfrage, besonders nach dem Öffnen einer erhaltenen Datei, ist ein Alarmsignal."],
   "tips": ["Geben Sie Ihr Passwort nur für eine selbst gestartete Aktion ein.", "Lesen Sie den Dialogtext: Welches Programm verlangt was?", "Arbeiten Sie nie dauerhaft mit dem root-Konto.", "Diese Anwendung fragt das Passwort nur ab, um die Firewall zu deaktivieren, einen Port zu öffnen, SSH zu aktivieren oder ein Update zu installieren."]},
  {"id": "ransomware_response", "title": "Was tun bei einem Angriff?", "summary": "Trennen, nicht zahlen, melden, wiederherstellen: die richtigen Schritte begrenzen den Schaden.",
   "details": ["Ändern Dateien ihren Namen, werden unlesbar oder erscheint eine Lösegeldforderung: Sofort das Netzwerk trennen (WLAN, Kabel) und die anderen Geräte im selben Netz ausschalten. Nicht zahlen: Nichts garantiert den Schlüssel, und Sie finanzieren den nächsten Angriff.", "Informieren Sie Ihre IT-Verantwortlichen oder einen Fachmann, sichern Sie Beweise (Bildschirmfotos, Nachrichten) und erstatten Sie Anzeige. Installieren Sie das System sauber neu und stellen Sie dann Ihre Offline-Backups wieder her. Ändern Sie danach alle Passwörter von einem sauberen Gerät aus."],
   "tips": ["Erst trennen, dann nachdenken.", "Kein Lösegeld zahlen.", "Vorfall melden (Polizei, cybercrime.admin.ch in der Schweiz).", "Sauber neu installieren und aus einem sauberen Backup wiederherstellen."]},
  {"id": "extensions", "title": "Browser-Erweiterungen und Berechtigungen", "summary": "Eine Erweiterung kann alles lesen, was Sie im Browser sehen und tippen. Installieren Sie so wenige wie möglich.",
   "details": ["Erweiterungen verlangen oft „alle Daten auf Websites lesen und ändern“: genau das, was ein Spion braucht, um Passwörter und Kartennummern zu stehlen. Ehrliche Erweiterungen werden manchmal aufgekauft und mit einem Update zu Schadsoftware.", "Diese Anwendung listet Ihre Erweiterungen auf und markiert jene, die nicht aus einem offiziellen Store stammen. Misten Sie regelmäßig aus."],
   "tips": ["Nur bekannte Erweiterungen aus dem offiziellen Store mit vielen Nutzern installieren.", "Entfernen Sie, was Sie nicht mehr nutzen.", "Lehnen Sie von einer Website oder Werbung angebotene Erweiterungen ab.", "Prüfen Sie die verlangten Berechtigungen: Eine „Wetter“-Erweiterung muss Ihre E-Mails nicht lesen."]}
],
"it": [
  {"id": "click", "title": "Non cliccare mai senza leggere", "summary": "La maggior parte degli attacchi inizia con un clic riflesso su un link, un allegato o un pulsante «OK».",
   "details": ["Gli aggressori contano sulla fretta: un messaggio allarmante («il suo account sarà chiuso»), un'offerta limitata, un pacco in attesa. Prenditi tre secondi per leggere l'indirizzo del mittente, passare il mouse sul link per vedere dove porta davvero e chiederti se ti aspettavi quel messaggio.", "Un link può mostrare «www.miabanca.ch» e puntare a un sito completamente diverso. Sul computer, passa il mouse sul link: la vera destinazione appare in basso nella finestra. Sul telefono, tieni premuto per vederla."],
   "tips": ["Leggi l'indirizzo completo del mittente, non solo il nome visualizzato.", "Passa il mouse sui link prima di cliccare; nel dubbio digita tu stesso l'indirizzo del sito.", "Nessuna banca, amministrazione o servizio serio chiede una password via e-mail.", "Un messaggio che ti mette fretta è un segnale d'allarme, non un'urgenza."]},
  {"id": "phishing", "title": "Riconoscere il phishing", "summary": "Un messaggio falso imita un'azienda nota per farti inserire credenziali o numero di carta.",
   "details": ["Il phishing arriva via e-mail, SMS («smishing»), WhatsApp o telefonata. Il messaggio copia logo e stile di una banca, della Posta, di Swisscom, del fisco, di Amazon… e ti manda a una pagina di accesso che è una copia. Tutto ciò che inserisci va direttamente all'aggressore.", "Indizi classici: indirizzo del mittente approssimativo (support@swiss-post-secure.com), errori o frasi strane, saluto generico («Gentile cliente»), richiesta di un piccolo pagamento (dazio doganale di CHF 2.90), minaccia di blocco."],
   "tips": ["Non accedere mai da un link ricevuto: apri l'app o digita l'indirizzo ufficiale.", "Confronta l'indirizzo del sito con quello abituale, lettera per lettera.", "Segnala il messaggio all'azienda imitata ed eliminalo.", "Se hai inserito una password su un sito falso, cambiala subito ovunque la usi."]},
  {"id": "ceo_fraud", "title": "La direzione hackerata: truffa del CEO", "summary": "Un'e-mail apparentemente del capo o di un collega chiede un bonifico urgente o dati riservati.",
   "details": ["Gli aggressori studiano l'azienda (sito web, LinkedIn) e inviano poi un messaggio molto plausibile: «Sono in riunione, fai questo bonifico di CHF 12'000 prima di mezzogiorno, ti spiego dopo.» A volte la casella del dirigente è stata davvero violata, il che rende il messaggio autentico in apparenza.", "La leva è sempre la stessa: autorità, urgenza e riservatezza («non dirlo a nessuno»). Nessuna procedura normale funziona così."],
   "tips": ["Ogni richiesta di bonifico, cambio IBAN o dati sensibili si conferma per telefono, con un numero che già conosci.", "Diffida dell'urgenza e del segreto: sono la firma della truffa.", "Un indirizzo del mittente legittimo non prova nulla se l'account è stato violato.", "Adotta la regola dei quattro occhi per i pagamenti."]},
  {"id": "unusual_mail", "title": "Un'e-mail insolita? Verifica con un altro canale", "summary": "Un contatto noto che scrive in modo diverso, a un'ora strana, con un allegato inatteso: non rispondere nel filo.",
   "details": ["Quando un account e-mail viene violato, l'aggressore invia messaggi a tutti i contatti, spesso in risposta a conversazioni reali passate. Tono, lingua o firma possono cambiare leggermente, l'allegato è un «documento» o una «fattura» che nessuno aspettava.", "Il riflesso giusto è verificare con un altro canale: una chiamata, un SMS, una conversazione di persona. Non rispondere al messaggio stesso: l'aggressore legge le risposte."],
   "tips": ["Confronta lo stile: formule, lingua, firma, ora di invio.", "Non aprire un allegato che non aspettavi, nemmeno da un conoscente.", "Chiama la persona per confermare prima di aprire o pagare.", "Avvisa il contatto se pensi che il suo account sia stato violato."]},
  {"id": "double_ext", "title": "stipendi.xlsx.exe: la trappola della doppia estensione", "summary": "Un file chiamato «stipendi.xlsx.exe» o «fattura.pdf.sh» non è un foglio di calcolo né un PDF: è un programma.",
   "details": ["Il sistema guarda solo l'ultima estensione. «stipendi.xlsx.exe» è un eseguibile Windows, «rapporto.pdf.sh» uno script Linux, «foto.jpg.desktop» un lanciatore. Con un doppio clic esegui un programma sconosciuto con i tuoi diritti: può cifrare i tuoi documenti o rubare le password.", "Le estensioni pericolose su Linux sono tra l'altro .sh, .run, .bin, .desktop, .AppImage, .py, .pl e .deb da fonte sconosciuta. Su Windows: .exe, .scr, .bat, .cmd, .js, .vbs, .msi. Il sistema può anche nascondere le estensioni note, per questo conviene mostrarle."],
   "tips": ["Mostra sempre le estensioni dei file nel gestore dei file.", "Un documento non dovrebbe mai avere due estensioni.", "Non eseguire mai un file ricevuto via e-mail o messaggistica senza analizzarlo e verificarlo con il mittente.", "Su Linux un file si esegue solo se gli dai il permesso: non farlo per un file sconosciuto."]},
  {"id": "usb", "title": "Chiavette USB: trovate, regalate… o trappole", "summary": "Una chiavetta trovata in un parcheggio o ricevuta in regalo può contenere un trojan o persino fingersi una tastiera.",
   "details": ["Gli aggressori abbandonano di proposito chiavette infette vicino alle aziende: la curiosità fa il resto. Alcune chiavette «BadUSB» si dichiarano tastiera e digitano comandi al posto tuo in pochi secondi, senza che nessun file sia visibile.", "ClamAV Antivirus GUI analizza le chiavette prima di aprirle, ma questo non protegge da una chiavetta-tastiera né da un programma che avvii tu stesso. Una chiavetta di origine sconosciuta non si collega."],
   "tips": ["Non collegare mai una chiavetta USB di cui non conosci l'origine.", "Lascia terminare l'analisi automatica prima di aprire i file.", "Non eseguire alcun programma da una chiavetta, copia solo i documenti.", "Per scambiare file, preferisci una condivisione online o un invio cifrato."]},
  {"id": "malware_types", "title": "Virus, worm, trojan, cryptolocker: le differenze", "summary": "Sono tutti software malevoli, ma non entrano e non agiscono nello stesso modo.",
   "details": ["Un virus si attacca a un programma o a un documento e si propaga quando lo si apre. Un worm si diffonde da solo da un computer all'altro via rete, sfruttando una vulnerabilità, senza intervento umano. Un cavallo di Troia (trojan) si presenta come software utile (gioco, utilità, «lettore video») ma apre una porta di servizio: furto di password, spionaggio della webcam, controllo remoto.", "Un cryptolocker (ransomware) cifra i tuoi file e chiede un riscatto per la chiave. Arriva spesso tramite un allegato o un trojan. Senza backup i dati sono in genere persi, e pagare non garantisce nulla."],
   "tips": ["Il trojan è oggi il più diffuso: diffida dei software «gratuiti» fuori dalle fonti ufficiali.", "Un worm sfrutta le vulnerabilità: gli aggiornamenti sono la tua protezione.", "Contro un cryptolocker ti salva solo un backup offline.", "L'antivirus rileva le minacce note; quelle nuove a volte passano."]},
  {"id": "vulnerability", "title": "Cos'è una vulnerabilità di sicurezza?", "summary": "Un errore in un programma che permette a un aggressore di fare ciò che non dovrebbe poter fare.",
   "details": ["Il software contiene milioni di righe di codice scritte da esseri umani. Alcuni errori permettono di far crollare il programma, iniettare comandi o prendere il controllo della macchina semplicemente aprendo un'immagine, una pagina web o un documento manipolati. Ogni vulnerabilità nota riceve un numero CVE (per esempio CVE-2026-63072).", "Tra la pubblicazione di una vulnerabilità e la sua correzione, gli aggressori automatizzano l'attacco a tutti i computer non aggiornati. La scheda Sicurezza di questa applicazione mostra le vulnerabilità note dei programmi installati e se esiste una correzione."],
   "tips": ["Una vulnerabilità «critica» o «alta» senza correzione merita di disinstallare o non usare il programma interessato.", "Meno software hai installato, meno vulnerabilità hai.", "Browser e lettori di documenti sono i più esposti: tienili aggiornati.", "Una vulnerabilità non è un'infezione; è una porta non chiusa a chiave."]},
  {"id": "updates", "title": "Perché gli aggiornamenti sono vitali", "summary": "Gli aggiornamenti di sicurezza chiudono le vulnerabilità che gli aggressori già sfruttano.",
   "details": ["Un aggiornamento di sicurezza non porta novità visibili: corregge una vulnerabilità. Una volta pubblicata la correzione, la vulnerabilità è nota a tutti, aggressori compresi, che prendono di mira le macchine in ritardo. Un computer non aggiornato da mesi è un bersaglio facile.", "Su Linux Mint, il Gestore degli aggiornamenti e questa applicazione segnalano gli aggiornamenti di sicurezza (rosso), raccomandati (applicazioni) e scaglionati. Riavvia quando richiesto: alcune correzioni (kernel) sono attive solo dopo."],
   "tips": ["Installa gli aggiornamenti di sicurezza appena compaiono.", "Attiva gli aggiornamenti automatici se dimentichi spesso.", "Aggiorna anche le app Flatpak, le estensioni del browser e il firmware.", "Un software non più aggiornato dal produttore va sostituito."]},
  {"id": "passwords", "title": "Password e autenticazione a due fattori", "summary": "Una password lunga e unica per ogni servizio, più una seconda verifica: è la base.",
   "details": ["Quando un sito viene violato, le password rubate vengono provate automaticamente su centinaia di altri servizi. Riutilizzare la stessa password equivale a distribuire una chiave che apre tutte le tue porte. La lunghezza conta più della complessità: una frase di quattro o cinque parole è più sicura di «P@ssw0rd!».", "Un gestore di password (Bitwarden, KeePassXC…) crea e ricorda password uniche per te. L'autenticazione a due fattori (codice da app, chiave di sicurezza) blocca un aggressore anche se conosce la password."],
   "tips": ["Una password diversa per ogni servizio, gestita da un gestore di password.", "Attiva la doppia autenticazione prima di tutto su e-mail, banca e social.", "Non condividere mai un codice ricevuto via SMS, nemmeno con un «consulente».", "Verifica su haveibeenpwned.com se il tuo indirizzo compare in una fuga di dati."]},
  {"id": "backups", "title": "Backup: la tua assicurazione contro tutto", "summary": "Di fronte a un ransomware, un guasto o un furto, solo un backup recente e offline ti salva.",
   "details": ["Un backup utile è automatico, regolare e scollegato: un disco esterno che colleghi e poi scolleghi, o un servizio online con versioni. Un disco sempre collegato verrà cifrato insieme al computer da un cryptolocker.", "Regola 3-2-1: tre copie dei tuoi dati, su due supporti diversi, di cui una fuori sede. Verifica ogni tanto che un ripristino funzioni davvero."],
   "tips": ["Fai il backup almeno ogni settimana, ogni giorno per uso professionale.", "Scollega il disco di backup dopo l'uso.", "Conserva una copia altrove (altro luogo o servizio online).", "Prova il ripristino di un file una volta a trimestre."]},
  {"id": "downloads", "title": "Installa solo da fonti ufficiali", "summary": "Un «installer gratuito» trovato su un sito sconosciuto è il vettore numero uno dei trojan.",
   "details": ["Software pirata, «crack», falsi lettori video ed estensioni dubbie contengono molto spesso uno spyware. Su Linux Mint passa dal Gestore delle applicazioni, dai repository ufficiali o da Flathub, e verifica che un .deb scaricato provenga davvero dal sito del produttore.", "Questa applicazione segnala i programmi che non appartengono a nessun pacchetto e che modificano i tuoi file o si connettono a Internet: proprio per individuare questo tipo di installazione."],
   "tips": ["Gestore delle applicazioni, repository ufficiali, Flathub: nient'altro senza verifica.", "Un software a pagamento «gratis» è quasi sempre una trappola.", "Verifica la firma o l'impronta di un file scaricato quando il produttore la fornisce.", "Non lanciare uno script «curl … | bash» trovato su un forum senza capirlo."]},
  {"id": "fake_support", "title": "Falso supporto tecnico e falsi avvisi", "summary": "«Il tuo computer è infetto, chiama questo numero»: una pagina web non può saperlo. È una truffa.",
   "details": ["Una finestra a tutto schermo, un allarme sonoro, un logo Microsoft o Apple, un numero da chiamare: queste pagine vogliono farti installare un software di controllo remoto o pagare una «riparazione». Il vero supporto non ti chiama mai spontaneamente e non mostra avvisi nel browser.", "Chiudi la scheda o il browser (se serve con Ctrl+Alt+Canc o riavviando). Nulla è infetto finché non hai installato niente né concesso accessi."],
   "tips": ["Non chiamare mai un numero mostrato da un avviso web.", "Non installare mai un software di controllo remoto su richiesta di uno sconosciuto.", "Chiudi la pagina; se blocca, chiudi il browser.", "Gli unici avvisi affidabili sono quelli di questa applicazione e del sistema, mai di una pagina web."]},
  {"id": "phone_scam", "title": "Manipolazione telefonica (ingegneria sociale)", "summary": "Un «consulente» della tua banca, della polizia o di un fornitore ti chiama e ti mette fretta: riattacca e richiama il numero vero.",
   "details": ["L'ingegneria sociale sfrutta la fiducia e la paura, non la tecnica. Il numero visualizzato può essere falsificato, l'interlocutore conosce nome e indirizzo (spesso pubblici) e inventa uno scenario credibile: account violato, pagamento sospetto, pacco bloccato, familiare in difficoltà.", "Un vero impiegato non ti chiederà mai una password, un codice SMS, un bonifico su un «conto sicuro» né di installare un programma. Ogni urgenza imposta al telefono è sospetta."],
   "tips": ["Riattacca e richiama con il numero ufficiale sulla carta o sul sito.", "Non dare mai codici o password per telefono.", "Rifiuta qualsiasi installazione di software richiesta a distanza.", "Parlane con una persona di fiducia prima di agire: l'isolamento fa parte della manipolazione."]},
  {"id": "wifi", "title": "Wi-Fi pubblico e reti sconosciute", "summary": "Su una rete che non controlli, qualcuno può osservare o dirottare il tuo traffico.",
   "details": ["In un bar, un hotel o una stazione, la rete «Free_WiFi» può essere gestita da un aggressore. I siti https proteggono il contenuto, ma portali di accesso manipolati, falsi aggiornamenti e condivisioni di file aperte restano rischi.", "Il firewall attivo e l'accesso remoto (SSH) disattivato, come raccomanda questa applicazione, riducono ciò che il tuo computer espone agli altri membri della rete."],
   "tips": ["Preferisci l'hotspot del telefono a un Wi-Fi sconosciuto.", "Usa una VPN affidabile sulle reti pubbliche.", "Non accettare alcun «aggiornamento» proposto da un portale Wi-Fi.", "Tieni il firewall attivo e le condivisioni di file disattivate."]},
  {"id": "sudo", "title": "La password di amministratore non è un semplice «OK»", "summary": "Quando un programma chiede la tua password, ottiene tutti i diritti sul computer. Chiediti perché.",
   "details": ["Su Linux la tua password (sudo, pkexec) dà il controllo totale: installare software, leggere tutti i file, modificare il sistema. Un trojan che ottiene questa password può disattivare antivirus e firewall.", "Inseriscila solo per un'azione che hai avviato tu stesso e che capisci: aggiornamento, installazione da fonte ufficiale, impostazione di sistema. Una richiesta a sorpresa, soprattutto dopo aver aperto un file ricevuto, è un segnale d'allarme."],
   "tips": ["Inserisci la password solo per un'azione che hai avviato tu.", "Leggi il testo della finestra: quale programma chiede cosa?", "Non lavorare mai stabilmente con l'account root.", "Questa applicazione chiede la password solo per disattivare il firewall, aprire una porta, attivare SSH o installare un aggiornamento."]},
  {"id": "ransomware_response", "title": "Cosa fare in caso di attacco?", "summary": "Scollega, non pagare, segnala, ripristina: i gesti giusti limitano i danni.",
   "details": ["Se i file cambiano nome, diventano illeggibili o compare una richiesta di riscatto: taglia subito la rete (Wi-Fi, cavo) e spegni gli altri dispositivi collegati alla stessa rete. Non pagare: nulla garantisce la chiave, e finanzi il prossimo attacco.", "Avvisa il responsabile informatico o un professionista, conserva le prove (foto dello schermo, messaggi) e sporgi denuncia. Reinstalla il sistema da zero e poi ripristina i backup offline. Cambia quindi tutte le password da un dispositivo pulito."],
   "tips": ["Prima scollegare, poi riflettere.", "Non pagare il riscatto.", "Segnala l'incidente (polizia, cybercrime.admin.ch in Svizzera).", "Reinstalla da zero e ripristina da un backup pulito."]},
  {"id": "extensions", "title": "Estensioni del browser e permessi", "summary": "Un'estensione può leggere tutto ciò che vedi e digiti nel browser. Installane il meno possibile.",
   "details": ["Le estensioni chiedono spesso di «leggere e modificare tutti i dati dei siti web»: esattamente ciò che serve a uno spione per rubare password e numeri di carta. Estensioni oneste vengono a volte comprate e trasformate in malware con un aggiornamento.", "Questa applicazione elenca le tue estensioni e segnala quelle che non provengono da uno store ufficiale. Fai pulizia regolarmente."],
   "tips": ["Installa solo estensioni note, dallo store ufficiale, con molti utenti.", "Rimuovi quelle che non usi più.", "Rifiuta le estensioni proposte da un sito o da una pubblicità.", "Controlla i permessi richiesti: un «meteo» non ha bisogno di leggere le tue e-mail."]}
]
};
